"""Public language and option metadata, observed through the listing interface."""
import json, os, re, copy, fnmatch
META = json.loads(__loader__.get_data(os.path.join(os.path.dirname(__file__),'metadata.json')))

def table(name):
    lines=META['tables'].get(name,{}).get('machine','').splitlines()
    if not lines:return [],[]
    return lines[0].lstrip('#').split('\t'),[s.split('\t') for s in lines[1:]]

def pretty(headers,rows,machine=False,with_header=True,which=''):
    h=headers[:]
    if not h:return ''
    h[0]='#'+h[0]
    allrows=([h] if with_header else [])+rows
    if machine:return ''.join('\t'.join(row)+'\n' for row in allrows)
    widths=[max([len(h[i])]+[len(r[i]) for r in rows]) for i in range(len(h))]
    # Tabular listings right-align the version and output-format status columns.
    right={i for i,k in enumerate(headers) if k=='VER'}
    if which=='output-formats':right.update(range(1,len(headers)))
    result=[]
    for row in allrows:
        parts=[]
        for i,v in enumerate(row):
            if i==len(h)-1 and which!='output-formats': parts.append(v)
            elif i in right:parts.append(v.rjust(widths[i])+' ')
            else:parts.append(v.ljust(widths[i])+' ')
        result.append(''.join(parts)+'\n')
    return ''.join(result)

class Config:
    def __init__(self,prog='executable'):
        self.prog=prog
        self.languages={line.split(' [')[0]:' [disabled]' not in line for line in META['languages'].splitlines()}
        self.tables={key:table(key) for key in META['tables']}
        self.kinds={}
        _,rows=self.tables['kinds-full']
        for r in rows:self.kinds.setdefault(r[0],{})[r[1]]={'name':r[2],'enabled':r[3]=='yes','refonly':r[4]=='yes','row':r[1:]}
        self.maps={l:[] for l in self.languages}
        self.patterns={l:[] for l in self.languages}
        self.aliases={l:[] for l in self.languages}
        for l,ext in self.tables['map-extensions'][1]:self.maps[l].append(ext)
        for l,pat in self.tables['map-patterns'][1]:self.patterns[l].append(pat)
        for l,a in self.tables['aliases'][1]:self.aliases[l].append(a)
        self.fields={r[0] for r in self.tables['fields'][1] if r[3]=='NONE' and r[2]=='yes'}
        self.langfields={}
        for r in self.tables['fields'][1]:
            if r[3]!='NONE':self.langfields.setdefault(r[3],{})[r[1]]=r[2]=='yes'
        self.extras={r[1] for r in self.tables['extras'][1] if r[3]=='NONE' and r[2]=='yes'}
        self.langextras={}
        for r in self.tables['extras'][1]:
            if r[3]!='NONE':self.langextras.setdefault(r[3],{})[r[1]]=r[2]=='yes'
        self.pseudo={r[0] for r in self.tables['pseudo-tags'][1] if r[1]=='on'}
        self.output='u-ctags';self.format=2;self.sort='yes';self.excmd='mix';self.backward=False
        self.outfile=None;self.append=False;self.recurse=False;self.maxdepth=100000;self.links=True
        self.excludes=META['excludes'].splitlines()[1:];self.exceptions=[]
        self.force=None;self.eager=False;self.relative='no';self.limit=96
        self.quiet=False;self.verbose=False;self.machinable=False;self.listheader=True
        self.explicit_pseudo=False;self.pseudomod=False;self.filter=False;self.terminator=''
        self.xformat=None;self.printlang=False;self.if0=False;self.linedirectives=False
        self.header_ext=['h','H','hh','hpp','hxx','h++','inc','def']
        self.regex={};self.customlang=set();self.custom_kinds_order={};self.sep={}
        self.files=[];self.encoding=None;self.outencoding=None;self.ignore=[];self.defines={}
        self.putprefix=False;self.etags_include=[];self.totals=False;self.input_encoding={}
        self.roles_disable=set();self.custom_versions={};self.params={}
        self.options_none=False;self.languages_changed=False;self.interactive=None
    def lang(self,value):
        for l in self.languages:
            if l.lower()==value.lower():return l
        return None
    def kind_name(self,lang,letter):
        if letter=='F':return 'file'
        return self.kinds.get(lang,{}).get(letter,{}).get('name',letter)
    def letter(self,lang,name):
        for k,v in self.kinds.get(lang,{}).items():
            if v['name']==name:return k
