                    row=[l]+d['row'][:];row[3]='yes' if d['enabled'] else 'no';rows.append(row)
            rows.sort(key=lambda r:(r[0].lower(),r[1]))
        if name=='fields':
            for r in rows:r[2]='yes' if (r[0] in self.fields if r[3]=='NONE' else self.field_on(r[3],r[1])) else 'no'
        if name=='extras':
            for r in rows:r[2]='yes' if (r[1] in self.extras if r[3]=='NONE' else self.langextras.get(r[3],{}).get(r[1],False)) else 'no'
        if name=='pseudo-tags':
            for r in rows:r[1]='on' if r[0] in self.pseudo else 'off'
        if name in ('map-extensions','map-patterns','aliases'):
            key={'map-extensions':self.maps,'map-patterns':self.patterns,'aliases':self.aliases}[name]
            rows=[[l,x] for l in sorted(key,key=str.lower) for x in key[l]]
        if value and value.lower()!='all':
            langpart=value.split('.',1)[0] if name=='roles' else value
            l=self.lang(langpart) or langpart
            column=3 if name in ('fields','extras') else 1 if name=='subparsers' else 0
            if 'LANGUAGE' in headers or name=='subparsers':
                rows=[r for r in rows if r[column]==l]
                if name not in ('fields','extras','subparsers'):
                    headers.pop(column)
                    for r in rows:r.pop(column)
            if name=='roles' and '.' in value:
                spec=value.split('.',1)[1]
                if spec!='*':
                    names=re.findall(r'\{([^}]+)\}',spec)
                    letters=re.sub(r'\{[^}]+\}','',spec)
                    rows=[r for r in rows if r[0].split('/')[0] in letters or r[0].split('/')[1] in names]
        return headers,rows
    def listing(self,name,value=None):
        if name=='languages':
            return ''.join(l+('' if self.languages[l] else ' [disabled]')+'\n' for l in sorted(self.languages,key=str.lower))
        if name=='kinds':
