                order=[r[:1] for r in raw.splitlines() if r] if raw else list(self.kinds.get(l,{}))
                if alllangs:lines.append(l+('' if self.languages[l] else ' [disabled]')+'\n')
                for k in order:
                    if k not in self.kinds.get(l,{}):continue
