            lines=[];alllangs=not(value and value.lower()!='all')
            for l in langs:
                if not l:continue
                raw=META['perlang'].get(l,{}).get('kinds','')
                order=[r[:1] for r in raw.splitlines() if r] if raw else list(self.kinds.get(l,{}))
                if alllangs:lines.append(l+('' if self.languages[l] else ' [disabled]')+'\n')
                for k in order:
                    if k not in self.kinds.get(l,{}):continue
                    d=self.kinds[l][k]
                    desc=d['row'][-1]
                    lines.append(('    ' if alllangs else '')+k+'  '+desc+('' if d['enabled'] else ' [off]')+'\n')
            return ''.join(lines)
        if name=='maps':
            order=list(META['perlang'])
            # Historical maps listing uses parser registration order, not lexical order.
            order=[r.split()[0] for r in META['maps'].splitlines() if r.split()]+[l for l in self.customlang]
            if value and value.lower()!='all':order=[self.lang(value)]
            return ''.join(l.ljust(8)+' '+' '.join(self.patterns.get(l,[])+['*.'+e for e in self.maps.get(l,[])])+'\n' for l in order if l)
        if name=='excludes':
            h=['NAME'];rows=[[x] for x in sorted(self.excludes)]
        else:h,rows=self.getrows(name,value)
        return pretty(h,rows,self.machinable,self.listheader,name)
