"""Render tag records in vi, JSON, xref and Emacs formats."""
import re, json, os, copy
from model import compact

def escaped(s):
    return str(s).replace('\\','\\\\').replace('\t','\\t').replace('\n','\\n').replace('\r','\\r')

def pattern(t,c):
    line=t.source if t.pattern_text is None else t.pattern_text
    # Pattern length is a byte budget on the escaped search text.
    delim='?' if c.backward else '/'
    p='';truncated=False
    for i,ch in enumerate(line):
        part=('\\'+ch) if ch in ('\\',delim) or (ch=='$' and i==len(line)-1) else ch
        p+=part
        if c.limit and len(p.encode('utf-8','surrogateescape'))>=c.limit:
            truncated=i<len(line)-1
            break
    return delim+'^'+p+('' if t.pattern_short or truncated else '$')+delim

def fields(t,c):
    f=c.fields;out=[]
    name=c.kind_name(t.lang,t.kind)
    if 'K' in f: kind=name
    elif 'k' in f:kind=t.kind
    else:kind=''
    if kind:out.append(('kind:' if 'z' in f else '')+kind)
    if 'n' in f:out.append('line:'+str(t.line))
    if 'l' in f:out.append('language:'+t.lang)
    if t.scope and 's' in f:out.append(('scope:' if 'Z' in f else '')+t.scope_kind+':'+escaped(t.scope))
    if t.typeref and 't' in f:out.append('typeref:'+escaped(t.typeref))
    if t.file and 'f' in f:out.append('file:')
    if t.inherits is not None and 'i' in f:out.append('inherits:'+escaped(t.inherits))
    if t.access and 'a' in f:out.append('access:'+t.access)
    if t.implementation and 'm' in f:out.append('implementation:'+t.implementation)
    if t.signature and 'S' in f:out.append('signature:'+escaped(t.signature))
    if 'r' in f:out.append(('UCTAGS' if c.putprefix else '')+'roles:'+t.roles)
    if t.extras and 'E' in f:out.append(('UCTAGS' if c.putprefix else '')+'extras:'+','.join(t.extras))
    if t.custom.get('xpath') and 'x' in f:out.append('xpath:'+escaped(t.custom['xpath']))
    if t.end and 'e' in f:out.append(('UCTAGS' if c.putprefix else '')+'end:'+str(t.end))
    if 'epoch' in t.custom and 'T' in f:out.append(('UCTAGS' if c.putprefix else '')+'epoch:'+str(t.custom['epoch']))
    if t.nth is not None and 'o' in f:out.append(('UCTAGS' if c.putprefix else '')+'nth:'+str(t.nth))
    for k,v in t.custom.items():
        if k in ('xpath','epoch'):continue
        if c.field_on(t.lang,k):out.append(('UCTAGS' if c.putprefix else '')+k+':'+escaped(v))
    return out

def ctags_line(t,c):
    if c.excmd=='number' or (t.force_number and c.excmd!='pattern'):ex=str(t.line)
    else:ex=(str(t.line)+';' if c.excmd=='combine' else '')+pattern(t,c)
    s=escaped(t.name)+'\t'+escaped(t.path)+'\t'+ex
    if c.format!=1:
        fs=fields(t,c)
        if fs:s+=';"\t'+'\t'.join(fs)
    return s+'\n'

def json_line(t,c):
    f=c.fields;d={'_type':'tag'}
    if 'N' in f:d['name']=t.name
    if 'F' in f:d['path']=t.path
    if 'P' in f:d['pattern']=False if t.force_number else pattern(t,c)
    if 'C' in f:d['compact']=compact(t.source)
    if 'f' in f and t.file:d['file']=True
    if 'l' in f:d['language']=t.lang
    if 'n' in f:d['line']=t.line
    if 't' in f and t.typeref:d['typeref']=t.typeref
    if f & {'k','K','z'}:d['kind']=c.kind_name(t.lang,t.kind)
    if 'i' in f and t.inherits is not None:d['inherits']=t.inherits if t.inherits else False
    if 'a' in f and t.access:d['access']=t.access
    if 'm' in f and t.implementation:d['implementation']=t.implementation
    if 'S' in f and t.signature:d['signature']=t.signature
    if f & {'s','Z'} and t.scope:d['scope']=t.scope
    if f & {'s','p','Z'} and t.scope:d['scopeKind']=t.scope_kind
    if 'r' in f:d['roles']=t.roles
    if 'E' in f and t.extras:d['extras']=','.join(t.extras)
    if 'x' in f and t.custom.get('xpath'):d['xpath']=t.custom['xpath']
    if 'e' in f and t.end:d['end']=t.end
    if 'T' in f and 'epoch' in t.custom:d['epoch']=t.custom['epoch']
    if 'o' in f and t.nth is not None:d['nth']=t.nth
    for k,v in t.custom.items():
        if k not in ('xpath','epoch') and c.field_on(t.lang,k):d[k]=v
    if len(d)==1:return ''
    return json.dumps(d,ensure_ascii=False)+'\n'

def field_value(t,c,spec):
    name=c.kind_name(t.lang,t.kind)
    values={'N':t.name,'name':t.name,'F':t.path,'input':t.path,'P':pattern(t,c),'pattern':pattern(t,c),
        'C':compact(t.source),'compact':compact(t.source),'k':t.kind,'K':name,'kind':name,'z':name,
        'n':str(t.line),'line':str(t.line),'l':t.lang,'language':t.lang,'S':t.signature,'signature':t.signature,
        'a':t.access,'access':t.access,'i':t.inherits or '', 'inherits':t.inherits or '',
        's':t.scope,'Z':t.scope,'scope':t.scope,'p':t.scope_kind,'scopeKind':t.scope_kind,
        't':t.typeref,'typeref':t.typeref,'r':t.roles,'roles':t.roles,'R':'D' if t.roles=='def' else 'R',
        'E':','.join(t.extras),'extras':','.join(t.extras),'e':str(t.end) if t.end else '',
        'end':str(t.end) if t.end else '', 'f':'file' if t.file else '', 'o':str(t.nth) if t.nth is not None else '',
        'm':t.implementation,'implementation':t.implementation}
    values.update(t.custom)
    if '.' in spec:spec=spec.split('.',1)[1]
    return str(values.get(spec,''))

def xref_line(t,c):
    fmt=c.xformat or '%-16N %-10K %4n %-16F %C'
    def sub(m):
        if m.group(0)=='%%':return '%'
        flags,width,precision,key=m.groups();key=key[1:-1] if key.startswith('{') else key
        v=field_value(t,c,key)
        if precision:v=v[:int(precision[1:])]
        w=int(width or 0)
        return v.ljust(w) if '-' in flags else v.rjust(w)
