def etags_output(tags,c,paths):
    result=''
    for path in paths:
        chunk=''
        for t in tags:
            if t.path!=path or t.kind=='F':continue
            line=t.source
            # C family etags search hints end just after the tagged identifier.
            if t.lang in ('C','C++','CPreProcessor'):
                m=re.search(r'(?<!\w)'+re.escape(t.name)+r'(?!\w)',line)
                if m:line=line[:m.end()]+(line[m.end():m.end()+1] if line[m.end():m.end()+1] in ('(',' ') else '')
            chunk+=line+'\x7f'+t.name+'\x01'+str(t.line)+','+str(t.offset)+'\n'
