def pseudo_lines(c,languages):
    data=[]
    def add(name,value,desc,lang=None,kind=None):
        if name not in c.pseudo and not(name=='JSON_OUTPUT_VERSION' and c.output=='json' and not c.pseudomod):return
        if c.output=='json':
            if name in ('TAG_FILE_FORMAT','TAG_OUTPUT_MODE','TAG_OUTPUT_FILESEP'):return
            d={'_type':'ptag','name':name}
            if lang:d['parserName']=lang
            if kind:d['kindName']=kind
            d['path']=str(value);d['pattern']=desc
            data.append(json.dumps(d,ensure_ascii=False)+'\n')
        else:
            desc=desc.replace('\\','\\\\').replace('/','\\/')
            data.append('!_'+name+('!'+lang if lang else '')+('!'+kind if kind else '')+'\t'+str(value)+'\t/'+desc+'/\n')
    from info import META
    add('TAG_FILE_FORMAT',c.format,'original format' if c.format==1 else 'extended format; --format=1 will not append ;" to lines')
    add('TAG_FILE_SORTED',{'yes':1,'no':0,'foldcase':2}[c.sort],'0=unsorted, 1=sorted, 2=foldcase')
    add('TAG_PROGRAM_AUTHOR','Universal Ctags Team','')
    add('TAG_PROGRAM_NAME','Universal Ctags','Derived from Exuberant Ctags')
    add('TAG_PROGRAM_URL','https://ctags.io/','official site')
    add('TAG_PROGRAM_VERSION','6.2.0','1cdb801')
    add('TAG_OUTPUT_MODE',c.output,'u-ctags or e-ctags')
    add('TAG_OUTPUT_FILESEP','slash','slash or backslash')
    add('TAG_PATTERN_LENGTH_LIMIT',c.limit,'0 for no limit')
    add('TAG_PROC_CWD',os.getcwd().rstrip('/')+'/','')
    add('TAG_OUTPUT_VERSION','1.1','current.age')
    add('TAG_OUTPUT_EXCMD',{'mix':'mixed','number':'number','pattern':'pattern','combine':'combineV2'}[c.excmd],'number, pattern, mixed, or combineV2')
    if c.outencoding or c.encoding:add('TAG_FILE_ENCODING',c.outencoding or 'utf-8','')
    if c.output=='json':add('JSON_OUTPUT_VERSION','1.0','in development')
    for r in c.tables['extras'][1]:
        l=r[3]
        if (l=='NONE' and r[1] in c.extras) or (l in languages and c.langextras.get(l,{}).get(r[1])):
            add('TAG_EXTRA_DESCRIPTION',r[1],r[-1],None if l=='NONE' else l)
    for r in c.tables['fields'][1]:
        l=r[3]
        if r[1]=='NONE':continue
        if (l=='NONE' and r[0] in c.fields) or (l in languages and c.field_on(l,r[1])):
            add('TAG_FIELD_DESCRIPTION',r[1],r[-1],None if l=='NONE' else l)
    for l in languages:
        for k,d in c.kinds.get(l,{}).items():
            if d['enabled']:add('TAG_KIND_DESCRIPTION',k+','+d['name'],d['row'][-1],l)
        version=META['perlang'].get(l,{}).get('version','').strip().split(': ')[-1] or '0.0'
        add('TAG_PARSER_VERSION',version,'current.age',l)
        for r in c.tables['roles'][1]:
            if r[0]==l:
                k,kname=r[1].split('/',1)
                if c.kinds.get(l,{}).get(k,{}).get('enabled'):add('TAG_ROLE_DESCRIPTION',r[2],r[-1],l,kname)
