        if 'qualified' in c.extras and t.scope:
            sep=c.sep.get(t.lang, '.' if t.lang in ('Python','Java','Go','Rust','Ruby','JavaScript','TypeScript','JSON','C#','Lua','SQL') else '::')
            do=True
