def render(tags,c,languages,paths):
    filtered=[]
    for t in tags:
        if not c.kind_on(t):continue
        if t.file and 'fileScope' not in c.extras:continue
        if t.roles!='def' and 'reference' not in c.extras:continue
        if 'guest' in t.extras and 'guest' not in c.extras:continue
        if 'anonymous' in t.extras and 'anonymous' not in c.extras:continue
        if (t.lang,t.kind,t.roles) in c.roles_disable:continue
        filtered.append(t)
        if 'qualified' in c.extras and t.scope:
            sep=c.sep.get(t.lang, '.' if t.lang in ('Python','Java','Go','Rust','Ruby','JavaScript','TypeScript','JSON','C#','Lua','SQL') else '::')
            do=True
            if t.lang in ('C','C++') and t.kind in ('e','l','z','D'):do=False
