"""User-defined line and multiline regular-expression parsers."""
import re
from model import compact

def split_definition(value):
    if not value:return []
    delim=value[0];out=[];s='';i=1
    while i<len(value):
        ch=value[i]
        if ch=='\\' and i+1<len(value):
            if value[i+1]==delim:s+=delim;i+=2;continue
            s+=ch+value[i+1];i+=2;continue
        if ch==delim:out.append(s);s=''
        else:s+=ch
        i+=1
    out.append(s);return out

def posix_pattern(p):
    for key,value in {'alpha':'A-Za-z','alnum':'A-Za-z0-9','digit':'0-9','blank':' \\t','space':'\\s','word':'A-Za-z0-9_','lower':'a-z','upper':'A-Z','xdigit':'0-9A-Fa-f'}.items():
        p=p.replace('[:'+key+':]',value)
    return p

def compile_rule(c,lang,spec,multiline=False):
    from cli import warn
    parts=split_definition(spec)
    if len(parts)<3:
        warn(c,'Incomplete regex definition: '+spec);return
    pat,name,kind=parts[:3];flags=parts[3] if len(parts)>3 else ''
    # An omitted kind uses the conventional generic regex kind.
    kd=kind.split(',') if kind else ['r','regex','regex']
    letter=kd[0] or 'r';kname=kd[1] if len(kd)>1 and kd[1] else letter;desc=kd[2] if len(kd)>2 else kname
    if letter not in c.kinds.setdefault(lang,{}):c.kinds[lang][letter]={'name':kname,'enabled':True,'refonly':False,'row':[letter,kname,'yes','no','0','NONE','0',desc]}
    pat=posix_pattern(pat)
    if 'b' in flags and 'e' not in flags:
        pat=pat.replace(r'\(', '(').replace(r'\)',')').replace(r'\+','+').replace(r'\|','|')
    try:r=re.compile(pat,re.M | (re.I if 'i' in flags or '{icase}' in flags else 0) | (re.S if multiline and '{mgroup' not in flags else 0))
    except re.error as e:warn(c,'regcomp '+str(e));return
    c.regex.setdefault(lang,[]).append((r,name,letter,flags,multiline))

def parse(src):
    stack=[]
    for r,template,k,flags,multi in src.config.regex.get(src.lang,[]):
        regions=[(0,src.text)] if multi else [(no,line) for no,line in enumerate(src.lines,1)]
        for no,text in regions:
            m=r.search(text)
            if not m:continue
            try:name=m.expand(template)
            except re.error:name=template
            name=name.strip()
            line=src.line_at(m.start()) if multi else no
            mg=re.search(r'\{mgroup=(\d+)\}',flags)
            if multi and mg:
                try:line=src.line_at(m.start(int(mg[1])))
                except:pass
            scope='';sk=''
            if '{scope=clear}' in flags:stack.clear()
            if '{scope=pop}' in flags and stack:stack.pop()
            if stack and any(x in flags for x in ('{scope=ref}','{scope=push}')):scope,sk=stack[-1]
            if '{placeholder}' not in flags:
                t=src.add(name,line,k,scope=scope,scope_kind=sk)
                if t:
                    custom=re.findall(r'\{_field=([^:}]+):([^}]+)\}',flags)
                    for key,val in custom:
                        try:t.custom[key]=m.expand(val)
                        except:t.custom[key]=val
                    ex=re.findall(r'\{_extra=([^}]+)\}',flags)
                    t.extras.extend(ex)
            if '{scope=push}' in flags:stack.append((scope+'::'+name if scope else name,src.config.kind_name(src.lang,k)))
    src.tags.sort(key=lambda t:t.line)
    return src.tags
