def perl(s):
    for no,line in enumerate(s.lines,1):
        if line.lstrip().startswith('#'):continue
        m=re.match(r'\s*package\s+([\w:]+)',line)
        if m:s.add(m[1],no,s.config.letter(s.lang,'package'))
        m=re.match(r'\s*sub\s+([\w:]+)',line)
        if m:s.add(m[1],no,s.config.letter(s.lang,'subroutine'))
        m=re.match(r'\s*use\s+constant\s+([\w]+)',line)
        if m:s.add(m[1],no,s.config.letter(s.lang,'constant'))
        m=re.match(r'\s*format\s+([\w]+)',line)
        if m:s.add(m[1],no,s.config.letter(s.lang,'format'))
    return s.tags

def awk(s):
    for no,line in enumerate(s.lines,1):
        m=re.match(r'\s*function\s+([\w]+)\s*\(',line)
        if m:s.add(m[1],no,'f')
    return s.tags

def vim(s):
    function=[]
    for no,line in enumerate(s.lines,1):
        if line.lstrip().startswith('"'):continue
        m=re.match(r'\s*(?:fu(?:n(?:c(?:tion)?)?)?|def)!?\s+([^\s(]+)\s*(\([^)]*\))',line)
        if m:function.append(s.add(m[1],no,'f',signature=m[2]));continue
        if re.match(r'\s*(?:endf(?:unction)?|enddef)\b',line):
            if function:function.pop().end=no
            continue
        m=re.match(r'\s*(let|var|const)\s+([^\s=:]+(?::[^\s=]+)?)\s*(?:[:=])',line)
        if m:s.add(m[2],no,'C' if m[1]=='const' else 'v')
        m=re.match(r'\s*com(?:mand)?!?\s+(?:-\S+\s+)*([A-Z]\w*)',line)
        if m:s.add(m[1],no,'c')
        m=re.match(r'\s*augroup\s+(\w+)',line)
        if m and m[1].upper()!='END':s.add(m[1],no,'a')
        m=re.match(r'\s*(?:[nvsxoiclt]?noremap|[nvsxoiclt]?map)!?\s+(?:<[^>]+>\s+)*([^\s]+)',line)
        if m:s.add(m[1],no,'m')
    return s.tags

def fortran(s):
    stack=[]
    def context():
        return (stack[-1][1],stack[-1][0]) if stack else ('','')
    for no,line in enumerate(s.lines,1):
        raw=line.split('!')[0]
        if not raw.strip() or (s.path.endswith(('.f','.for','.f77')) and raw[0:1] in ('c','C','*')):continue
        if re.match(r'\s*end\s*(?:module|type|function|subroutine|program|interface|block\s*data)?\b',raw,re.I):
            if stack:stack.pop()
            continue
        m=re.match(r'\s*(?:[\w()*,=]+\s+)*(module|program|subroutine|function|interface)\s+(\w+)',raw,re.I)
        if m:
            word=m[1].lower();name=m[2]
            if word=='module' and name.lower()=='procedure':continue
            k=s.config.letter(s.lang,word);sc,sk=context();kw={'scope':sc,'scope_kind':sk}
            end=m.end(2)
            if end<len(raw):kw.update(pattern_text=line[:end+1],pattern_short=True)
            if word=='subroutine':
                sig=re.search(r'\([^)]*\)',raw[end:])
                if sig:kw['signature']=sig[0]
            s.add(name,no,k,**kw);stack.append((word,name));continue
        m=re.match(r'\s*type\s*(?:,\s*[^:]+)?\s*::\s*(\w+)',raw,re.I)
        if not m:m=re.match(r'\s*type\s+(\w+)\s*$',raw,re.I)
        if m:
            sc,sk=context();s.add(m[1],no,s.config.letter(s.lang,'type'),scope=sc,scope_kind=sk);stack.append(('type',m[1]));continue
        if '::' in raw:
            start=raw.index('::')+2;sc,sk=context()
            local=sk in ('function','subroutine','program')
            k=s.config.letter(s.lang,'component' if sk=='type' else 'local' if local else 'variable')
            body=raw[start:];depth=0;begin=0
