            if stack:stack.pop()
            continue
        parent=stack[-1] if stack else None
        node={'name':m[2],'attrs':m[3],'pos':m.start(),'parent':parent,'children':[]}
        (parent['children'] if parent else roots).append(node);nodes.append(node)
        if not m[4]:stack.append(node)
    def xpath(node):
        parent=node['parent'];siblings=parent['children'] if parent else roots
        same=[x for x in siblings if x['name']==node['name']]
        name=node['name']+('['+str(same.index(node)+1)+']' if len(same)>1 else '')
        return (xpath(parent) if parent else '')+'/'+name
    for n in nodes:
        no=s.line_at(n['pos'])
        for m in re.finditer(r'([\w:.-]+)\s*=\s*(["\'])(.*?)\2',n['attrs'],re.S):
            key,val=m[1],m[3]
            if key=='id':s.add(val,no,'i',custom={'xpath':xpath(n)+'/@id'})
            elif key.startswith('xmlns:'):s.add(key[6:],no,'n',custom={'uri':val})
    return s.tags

